17	// Shared box-decode primitives for the two YOLO head contracts published by
18	// this sample:
19	//   * direct-LTRB heads (YOLO26): box maps carry 4 float distances per cell.
20	//   * DFL heads (YOLOv5u/v8/v9/v10/yolo11/yolo12/yolov13): box maps carry
21	//     4 x 16 raw logits per cell that softmax into distance distributions.
22	// The math mirrors runtime/python/rdk_yolo_utils/postprocess.py so the C++
23	// and Python runtimes stay contract-compatible.
24	
25	#ifndef RUNTIME_CPP_COMMON_DECODE_H_
26	#define RUNTIME_CPP_COMMON_DECODE_H_
27	
28	#include <algorithm>
29	#include <cmath>
30	#include <limits>
31	
32	namespace yolo {
33	
34	// Box-decode protocols selectable per model.
35	enum class BoxDecode { kUnknown, kDirectLtrb, kDfl };
36	
37	// DFL heads distribute each side distance over this many bins.
38	const int kDflBins = 16;
39	
40	// Channels carried by one box-map cell under each protocol.
41	inline int box_channels(BoxDecode decode) {
42	  if (decode == BoxDecode::kDirectLtrb) return 4;
43	  if (decode == BoxDecode::kDfl) return 4 * kDflBins;
44	  return 0;
45	}
46	
47	// Maps an observed box-map channel count to a decode protocol.
48	inline BoxDecode box_decode_from_channels(int channels) {
49	  if (channels == 4) return BoxDecode::kDirectLtrb;
50	  if (channels == 4 * kDflBins) return BoxDecode::kDfl;
51	  return BoxDecode::kUnknown;
52	}
53	
54	inline float sigmoid(float value) {
55	  if (value >= 0.0f) return 1.0f / (1.0f + std::exp(-value));
56	  const float exp_value = std::exp(value);
57	  return exp_value / (1.0f + exp_value);
58	}
59	
60	// Raw-logit threshold equivalent to `sigmoid(raw) >= score_threshold`.
61	// Thresholds outside (0, 1) degenerate to +/- infinity, matching the
62	// behaviour of the released detect sample.
63	inline float raw_logit_threshold(float score_threshold) {
64	  if (score_threshold <= 0.0f) return -std::numeric_limits<float>::infinity();
65	  if (score_threshold >= 1.0f) return std::numeric_limits<float>::infinity();
66	  return -std::log(1.0f / score_threshold - 1.0f);
67	}
68	
69	// Letterbox/resize transform mapping model-input coordinates back to the
70	// source image.
71	struct ImageTransform {
72	  float scale_x = 1.0f;
73	  float scale_y = 1.0f;
74	  int shift_x = 0;
75	  int shift_y = 0;
76	};
77	
78	// Direct-LTRB heads: the four distances are stored as-is.
79	inline void decode_box_ltrb(const float* box4, float* ltrb4) {
80	  ltrb4[0] = box4[0];
81	  ltrb4[1] = box4[1];
82	  ltrb4[2] = box4[2];
83	  ltrb4[3] = box4[3];
84	}
85	
86	// DFL heads: softmax over 16 bins per side, then the bin-index expectation
87	// is the distance (numerically stabilised like the Python softmax).
88	inline void decode_box_dfl(const float* box64, float* ltrb4) {
89	  for (int side = 0; side < 4; ++side) {
90	    const float* bins = box64 + side * kDflBins;
91	    float max_value = bins[0];
92	    for (int j = 1; j < kDflBins; ++j) {
93	      if (bins[j] > max_value) max_value = bins[j];
94	    }
95	    float sum = 0.0f;
96	    float expectation = 0.0f;
97	    for (int j = 0; j < kDflBins; ++j) {
98	      const float weight = std::exp(bins[j] - max_value);
99	      sum += weight;
100	      expectation += weight * j;
101	    }
102	    ltrb4[side] = expectation / sum;
103	  }
104	}
105	
106	// Converts per-cell distances around a grid centre to input-image corners.
107	inline void box_from_distances(float grid_center_x, float grid_center_y,
108	                               const float* ltrb4, float stride, float* x1,
109	                               float* y1, float* x2, float* y2) {
110	  *x1 = (grid_center_x - ltrb4[0]) * stride;
111	  *y1 = (grid_center_y - ltrb4[1]) * stride;
112	  *x2 = (grid_center_x + ltrb4[2]) * stride;
113	  *y2 = (grid_center_y + ltrb4[3]) * stride;
114	}
115	
116	// Maps input-image coordinates back to source-image coordinates and clamps
117	// them to the image bounds. Returns false for degenerate boxes.
118	inline bool map_to_source(float* x1, float* y1, float* x2, float* y2,
119	                          const ImageTransform& transform, int image_w,
120	                          int image_h) {
121	  *x1 = (*x1 - transform.shift_x) / transform.scale_x;
122	  *y1 = (*y1 - transform.shift_y) / transform.scale_y;
123	  *x2 = (*x2 - transform.shift_x) / transform.scale_x;
124	  *y2 = (*y2 - transform.shift_y) / transform.scale_y;
125	  *x1 = std::max(0.0f, std::min(*x1, static_cast<float>(image_w)));
126	  *y1 = std::max(0.0f, std::min(*y1, static_cast<float>(image_h)));
127	  *x2 = std::max(0.0f, std::min(*x2, static_cast<float>(image_w)));
128	  *y2 = std::max(0.0f, std::min(*y2, static_cast<float>(image_h)));
129	  return *x2 > *x1 && *y2 > *y1;
130	}
131	
132	}  // namespace yolo
133	
134	#endif  // RUNTIME_CPP_COMMON_DECODE_H_
